import{_ as e,c as t,o,a2 as r}from"./chunks/framework.DdOM6S6U.js";const g=JSON.parse('{"title":"ImpersonateMiddleware","description":"","frontmatter":{"sidebarPos":7,"sidebarTitle":"ImpersonateMiddleware"},"headers":[],"relativePath":"system-reference/backend/http/middleware/impersonate.md","filePath":"system-reference/backend/http/middleware/impersonate.md","lastUpdated":1778363927000}'),a={name:"system-reference/backend/http/middleware/impersonate.md"},s=r('<h1 id="impersonatemiddleware" tabindex="-1">ImpersonateMiddleware <a class="header-anchor" href="#impersonatemiddleware" aria-label="Permalink to &quot;ImpersonateMiddleware&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Middleware/ImpersonateMiddleware.php</code><br><strong>Alias</strong>: <code>modularous.impersonate</code><br><strong>Part of</strong>: <code>modularous.core</code> group</p><p>Activates user impersonation for the current request and shares the impersonation config with the master Blade layout.</p><h2 id="how-impersonation-works" tabindex="-1">How Impersonation Works <a class="header-anchor" href="#how-impersonation-works" aria-label="Permalink to &quot;How Impersonation Works&quot;">​</a></h2><p>When an admin starts impersonating another user, the target user&#39;s ID is stored in the session under the <code>&#39;impersonate&#39;</code> key. On every subsequent request this middleware:</p><ol><li>Checks for <code>session(&#39;impersonate&#39;)</code>.</li><li>If present, calls <code>auth()-&gt;guard(Modularous::getAuthGuardName())-&gt;onceUsingId($targetId)</code> — this swaps the authenticated user <strong>for the current request only</strong>, without affecting the session&#39;s real authenticated user.</li><li>Composes <code>modularous::layouts.master</code> with the impersonation config (<code>get_modularous_impersonation_config()</code>), which provides the frontend with the data needed to render the &quot;stop impersonating&quot; banner.</li></ol><h2 id="impersonation-config" tabindex="-1">Impersonation Config <a class="header-anchor" href="#impersonation-config" aria-label="Permalink to &quot;Impersonation Config&quot;">​</a></h2><p><code>get_modularous_impersonation_config()</code> returns an array used by the admin panel to:</p><ul><li>Show or hide the impersonation banner.</li><li>Provide the &quot;stop impersonating&quot; route.</li><li>Display the impersonated user&#39;s name.</li></ul><h2 id="starting-stopping-impersonation" tabindex="-1">Starting / Stopping Impersonation <a class="header-anchor" href="#starting-stopping-impersonation" aria-label="Permalink to &quot;Starting / Stopping Impersonation&quot;">​</a></h2><p>Impersonation is controlled by two routes:</p><table><thead><tr><th>Route</th><th>Action</th></tr></thead><tbody><tr><td><code>admin.impersonate</code></td><td>Sets <code>session(&#39;impersonate&#39;, $userId)</code></td></tr><tr><td><code>admin.impersonate.stop</code></td><td>Removes <code>session(&#39;impersonate&#39;)</code></td></tr></tbody></table><p>These routes are excluded from the intended-URL store in <code>AuthenticateMiddleware</code>.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>onceUsingId()</code> is request-scoped — the real session user is never changed. If the browser is closed and reopened, the impersonation is gone.</li><li>Superadmin-level permission check before setting the session key should be enforced at the controller level, not in this middleware.</li></ul>',15),n=[s];function i(d,l,c,p,h,m){return o(),t("div",null,n)}const f=e(a,[["render",i]]);export{g as __pageData,f as default};
